    49→    executor_node: u16,
    50→
    51→    /// Log directory
    52→    #[arg(long, default_value = "~/.spice/distributed/logs")]
    53→    log_dir: PathBuf,
    54→
    55→    /// Working directory
    56→    #[arg(long, default_value = "~/.spice/distributed")]
    57→    work_dir: PathBuf,
    58→
    59→    /// Project directory
    60→    #[arg(long, default_value = ".")]
    61→    project_dir: PathBuf,
    62→
    63→    /// Path to spiced binary
    64→    #[arg(long)]
    65→    spiced_path: Option<PathBuf>,
    66→
    67→    /// Skip automatic TLS initialization
    68→    #[arg(long)]
    69→    no_tls_init: bool,
    70→
    71→    /// Skip health checks after startup
    72→    #[arg(long)]
    73→    no_health_check: bool,
    74→
    75→    /// Start and exit (don't wait for Ctrl+C)
    76→    #[arg(short, long)]
    77→    detach: bool,
    78→}
    79→
    80→pub async fn execute(args: StartArgs) -> Result<()> {
    81→    // Expand tilde in paths
    82→    let work_dir = expand_tilde(&args.work_dir);
    83→    let log_dir = expand_tilde(&args.log_dir);
    84→    let project_dir = expand_tilde(&args.project_dir);
    85→
    86→    // Check if cluster already running
    87→    if state_exists(&work_dir) {
    88→        output::error("Cluster is already running. Use 'distributed stop' to stop it first.");
    89→        return Err(anyhow::anyhow!("Cluster already running"));
    90→    }
    91→
    92→    // Build configuration
    93→    let mut config = ClusterConfig::default();
    94→    config.num_executors = args.executors;
    95→    config.scheduler.http_port = args.scheduler_http;
    96→    config.scheduler.flight_port = args.scheduler_flight;
    97→    config.scheduler.node_port = args.scheduler_node;
    98→    config.executors.base_http_port = args.executor_http;
    99→    config.executors.base_node_port = args.executor_node;
   100→    config.paths.log_dir = log_dir;
   101→    config.paths.work_dir = work_dir;
   102→    config.paths.project_dir = project_dir;
   103→    if let Some(spiced_path) = args.spiced_path {
   104→        config.paths.spiced_path = expand_tilde(&spiced_path);
   105→    }
   106→    config.detach = args.detach;
   107→    config.skip_tls_init = args.no_tls_init;
   108→    config.skip_health_check = args.no_health_check;
   109→
   110→    // Validate spiced binary exists
   111→    if !config.paths.spiced_path.exists() {
   112→        output::error(&format!(
   113→            "spiced binary not found at: {}",
   114→            config.paths.spiced_path.display()
   115→        ));
   116→        output::info("Please install Spice.ai or specify the correct path with --spiced-path");
   117→        return Err(anyhow::anyhow!("spiced binary not found"));
   118→    }
   119→
   120→    output::info("Starting distributed Spice cluster...");
   121→
   122→    // Initialize TLS if needed
   123→    if !config.skip_tls_init {
   124→        output::info("Initializing TLS certificates...");
   125→        tls::ensure_tls_initialized().context("Failed to initialize TLS")?;
   126→
   127→        // Generate certificates for scheduler and executors
   128→        // Note: scheduler uses "scheduler1" as the cert name to match bash script convention
   129→        let mut node_names = vec!["scheduler1"];
   130→        let executor_names: Vec<String> = (0..config.num_executors)
   131→            .map(|i| config.executor_name(i))
   132→            .collect();
   133→        let executor_refs: Vec<&str> = executor_names.iter().map(String::as_str).collect();
   134→        node_names.extend(&executor_refs);
   135→
   136→        tls::ensure_certificates(&node_names).context("Failed to generate certificates")?;
   137→    }
   138→
   139→    // Start scheduler
   140→    output::info(&format!(
   141→        "Starting scheduler on port {}...",
   142→        config.scheduler.http_port
   143→    ));
   144→    let scheduler_node = process::start_scheduler(&config).context("Failed to start scheduler")?;
   145→
   146→    // Wait for scheduler health check
   147→    if !config.skip_health_check {
   148→        let health_check = HealthCheck::default();
   149→        let health_url = get_health_url(config.scheduler.http_port);
   150→        match health_check.wait_for_ready(&health_url).await {
   151→            Ok(()) => output::success("Scheduler is ready"),
   152→            Err(e) => {
   153→                output::error(&format!("Scheduler health check failed: {e}"));
   154→                output::info("Last 10 lines of scheduler log:");
   155→                if let Ok(tail) = process::read_log_tail(&scheduler_node.log_file, 10) {
   156→                    println!("{tail}");
   157→                }
   158→                // Clean up scheduler process
   159→                let _ = process::kill_process(scheduler_node.pid);
   160→                return Err(e);
   161→            }
   162→        }
   163→    }
   164→
   165→    // Start executors
   166→    let scheduler_addr = format!("127.0.0.1:{}", config.scheduler.node_port);
   167→    let mut executor_nodes: Vec<NodeState> = Vec::new();
   168→
   169→    for i in 0..config.num_executors {
   170→        let name = config.executor_name(i);
   171→        let http_port = config.executor_http_port(i);
   172→        let node_port = config.executor_node_port(i);
   173→
   174→        output::info(&format!("Starting {name} on port {http_port}..."));
   175→        let executor_node =
   176→            process::start_executor(&name, http_port, node_port, &config, &scheduler_addr)
   177→                .context(format!("Failed to start {name}"))?;
   178→
   179→        // Wait for executor health check
   180→        if !config.skip_health_check {
   181→            let health_check = HealthCheck::default();
   182→            let health_url = get_health_url(http_port);
   183→            match health_check.wait_for_ready(&health_url).await {
   184→                Ok(()) => output::success(&format!("{name} is ready")),
   185→                Err(e) => {
   186→                    output::error(&format!("{name} health check failed: {e}"));
   187→                    output::info(&format!("Last 10 lines of {name} log:"));
   188→                    if let Ok(tail) = process::read_log_tail(&executor_node.log_file, 10) {
   189→                        println!("{tail}");
   190→                    }
   191→                    // Clean up all processes
   192→                    let _ = process::kill_process(executor_node.pid);
   193→                    for node in &executor_nodes {
   194→                        let _ = process::kill_process(node.pid);
   195→                    }
   196→                    let _ = process::kill_process(scheduler_node.pid);
   197→                    return Err(e);
   198→                }
   199→            }
   200→        }
   201→
   202→        executor_nodes.push(executor_node);
   203→
   204→        // Delay between starting executors
   205→        if i < config.num_executors - 1 {
   206→            tokio::time::sleep(Duration::from_secs(2)).await;
   207→        }
   208→    }
   209→
   210→    // Save state
   211→    let state = ClusterState::new(
   212→        config.paths.project_dir.clone(),
   213→        scheduler_node.clone(),
   214→        executor_nodes.clone(),
   215→    );
   216→    save_state(&state, &config.paths.work_dir).context("Failed to save cluster state")?;
   217→
   218→    // Print status
   219→    println!();
   220→    output::success("Cluster started successfully!");
   221→    println!();
   222→    println!("Scheduler:");
   223→    println!(
   224→        "  scheduler (port {}): PID {}",
   225→        scheduler_node.http_port, scheduler_node.pid
   226→    );
   227→    println!();
   228→    println!("Executors:");
   229→    for node in &executor_nodes {
   230→        println!(
   231→            "  {} (port {}): PID {}",
   232→            node.name, node.http_port, node.pid
   233→        );
   234→    }
   235→    println!();
   236→    output::info(&format!(
   237→        "Logs directory: {}",
   238→        config.paths.log_dir.display()
   239→    ));
   240→    println!();
   241→
   242→    // Handle detach vs background mode
