    16→
    17→use anyhow::{Context, Result};
    18→use clap::Args;
    19→use serde::Serialize;
    20→use std::path::PathBuf;
    21→
    22→use crate::cluster::{health::*, paths::expand_tilde, process, state::*};
    23→use crate::output;
    24→
    25→#[derive(Args)]
    26→pub struct StatusArgs {
    27→    /// Working directory
    28→    #[arg(long, default_value = "~/.spice/distributed")]
    29→    work_dir: PathBuf,
    30→
    31→    /// Output status as JSON
    32→    #[arg(long)]
    33→    json: bool,
    34→}
    35→
    36→#[derive(Serialize, Clone)]
    37→struct NodeStatus {
    38→    name: String,
    39→    pid: u32,
    40→    http_port: u16,
    41→    status: String,
    42→}
    43→
    44→#[derive(Serialize)]
    45→struct ClusterStatus {
    46→    running: bool,
    47→    scheduler: NodeStatus,
    48→    executors: Vec<NodeStatus>,
    49→}
    50→
    51→pub async fn execute(args: StatusArgs) -> Result<()> {
    52→    // Expand tilde in paths
    53→    let work_dir = expand_tilde(&args.work_dir);
    54→
    55→    // Check if cluster is running
    56→    if !state_exists(&work_dir) {
    57→        if args.json {
    58→            let status = serde_json::json!({
    59→                "running": false,
    60→                "message": "No cluster is currently running"
    61→            });
    62→            println!("{}", serde_json::to_string_pretty(&status)?);
    63→        } else {
    64→            output::info("No cluster is currently running.");
    65→        }
    66→        return Ok(());
    67→    }
    68→
    69→    // Load state
    70→    let state = load_state(&work_dir).context("Failed to load cluster state")?;
    71→
    72→    // Check scheduler status
    73→    let scheduler_status = check_node_status(
    74→        &state.scheduler.name,
    75→        state.scheduler.pid,
    76→        state.scheduler.http_port,
    77→    )
    78→    .await;
    79→
    80→    // Check executor statuses
    81→    let mut executor_statuses = Vec::new();
    82→    for executor in &state.executors {
    83→        let status = check_node_status(&executor.name, executor.pid, executor.http_port).await;
    84→        executor_statuses.push(status);
    85→    }
    86→
    87→    // Output
    88→    if args.json {
    89→        let cluster_status = ClusterStatus {
    90→            running: true,
    91→            scheduler: scheduler_status.clone(),
    92→            executors: executor_statuses.clone(),
    93→        };
    94→        println!("{}", serde_json::to_string_pretty(&cluster_status)?);
    95→    } else {
    96→        println!("Cluster Status:");
    97→        println!();
    98→        println!("Scheduler:");
    99→        print_node_status(&scheduler_status);
   100→        println!();
   101→        println!("Executors:");
   102→        for executor_status in &executor_statuses {
   103→            print_node_status(executor_status);
   104→        }
   105→    }
   106→
   107→    Ok(())
   108→}
   109→
   110→async fn check_node_status(name: &str, pid: u32, http_port: u16) -> NodeStatus {
   111→    let is_alive = process::is_process_alive(pid);
   112→
   113→    let status = if !is_alive {
   114→        "stopped".to_string()
   115→    } else {
   116→        let health_check = HealthCheck::default();
   117→        let health_url = get_health_url(http_port);
   118→        match health_check.check_health(&health_url).await {
   119→            Ok(true) => "healthy".to_string(),
   120→            Ok(false) => "unhealthy".to_string(),
   121→            Err(_) => "not responding".to_string(),
   122→        }
   123→    };
   124→
   125→    NodeStatus {
   126→        name: name.to_string(),
   127→        pid,
   128→        http_port,
   129→        status,
   130→    }
   131→}
   132→
   133→fn print_node_status(status: &NodeStatus) {
   134→    let symbol = match status.status.as_str() {
   135→        "healthy" => "✓",
   136→        "stopped" => "✗",
   137→        "unhealthy" => "⚠",
   138→        "not responding" => "⚠",
   139→        _ => "?",
   140→    };
   141→
   142→    let colored_status = match status.status.as_str() {
   143→        "healthy" => ansi_colors::Color::Green.paint(&status.status).to_string(),
   144→        "stopped" => ansi_colors::Color::Red.paint(&status.status).to_string(),
