    if !is_process_alive(pid.as_raw() as u32) {
        return Ok(());
    }

    signal::kill(pid, Signal::SIGKILL).context("Failed to send SIGKILL")?;

    std::thread::sleep(Duration::from_secs(1));

    if is_process_alive(pid.as_raw() as u32) {
        return Err(anyhow!("Failed to kill process {pid}"));
    }

    Ok(())
}

